urlset:
{#- zola's built-in sitemap.xml, plus one rule: no /page/1/ entries.
    zola builds every paginated listing's /page/1/ as a stub that
    redirects to the listing itself, and lists both URLs. A sitemap is a
    statement about canonical, indexable URLs; Search Console reports a
    redirecting entry as "Page with redirect". page/2/ upward are real
    pages and stay. -#}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink is not ending_with(pat="/page/1/") %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
